    <script>
        (function() {

            let swiperLoaded = false;

            function loadSwiper(callback) {
                if (swiperLoaded) return callback();

                const script = document.createElement("script");
                script.src = "https://cdn.jsdelivr.net/npm/swiper@10/swiper-bundle.min.js";
                script.defer = true;

                script.onload = () => {
                    swiperLoaded = true;
                    callback();
                };

                document.body.appendChild(script);
            }

            function initSwipers() {

                // ===== COMMON SWIPERS =====
                const configs = {
                    mySwiper1: 3,
                };

                Object.entries(configs).forEach(([className, slidesView]) => {
                    if (!document.querySelector(`.${className}`)) return;

                    new Swiper(`.${className}`, {
                        slidesPerView: slidesView,
                        spaceBetween: 30,
                        loop: true,
                        freeMode: true,

                        breakpoints: {
                            280: {
                                slidesPerView: 1,
                                spaceBetween: 10
                            },
                            320: {
                                slidesPerView: 1,
                                spaceBetween: 10
                            },
                            480: {
                                slidesPerView: 2,
                                spaceBetween: 10
                            },
                            768: {
                                slidesPerView: Math.max(2, slidesView - 1),
                                spaceBetween: 10
                            },
                            1200: {
                                slidesPerView: slidesView,
                                spaceBetween: 10
                            },
                        },

                        autoplay: {
                            delay: 3500,
                            disableOnInteraction: true,
                            pauseOnMouseEnter: true,
                        },

                        navigation: {
                            nextEl: `.swiper-button-next${className.slice(-1)}`,
                            prevEl: `.swiper-button-prev${className.slice(-1)}`,
                        },

                        pagination: {
                            el: `.swiper-pagination${className.slice(-1)}`,
                            clickable: true,
                        },
                    });
                });


                // ===== SCROLL HEADER SWIPER =====
                const swiperContainer = document.querySelector(".scrollHeaderSwiper .swiper-wrapper");

                if (swiperContainer) {
                    const slides = swiperContainer.querySelectorAll(".swiper-slide");

                    if (slides.length < 4) {
                        const needed = 4 - slides.length;
                        for (let i = 0; i < needed; i++) {
                            swiperContainer.appendChild(slides[i % slides.length].cloneNode(true));
                        }
                    }

                    const swiperHeader = new Swiper(".scrollHeaderSwiper", {
                        slidesPerView: "auto",
                        loop: true,
                        speed: 6000,
                        autoplay: {
                            delay: 0,
                            disableOnInteraction: false,
                        },
                        allowTouchMove: false,
                    });

                    const swiperEl = document.querySelector(".scrollHeaderSwiper");

                    swiperEl.addEventListener("mouseenter", () => swiperHeader.autoplay.stop());
                    swiperEl.addEventListener("mouseleave", () => swiperHeader.autoplay.start());
                }
            }


            // ===== INTERSECTION OBSERVER =====
            const observer = new IntersectionObserver((entries, obs) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        loadSwiper(initSwipers);
                        obs.disconnect(); // run only once
                    }
                });
            }, {
                rootMargin: "200px" // preload slightly before visible
            });


            // Observe any swiper container
            document.querySelectorAll(".mySwiper1, .scrollHeaderSwiper").forEach(el => {
                observer.observe(el);
            });

        })();
    </script>

    <script defer>
        function getTimeRemaining(endTime) {
            const total = Date.parse(endTime) - Date.parse(new Date());
            const seconds = Math.floor((total / 1000) % 60);
            const minutes = Math.floor((total / 1000 / 60) % 60);
            const hours = Math.floor((total / (1000 * 60 * 60)) % 24);
            const days = Math.floor(total / (1000 * 60 * 60 * 24));

            return {
                total,
                days,
                hours,
                minutes,
                seconds
            };
        }

        function getEndTime() {
            return new Date(2026, 9, 15, 23, 59, 59);
        }


        function padZero(number) {
            return number < 10 ? '0' + number : number;
        }

        function initializeClock() {
            const countdownElement = document.getElementById('countdown');
            const countdownElement2 = document.getElementById('countdown2');
            const countdownElement3 = document.getElementById('countdown3');
            const countdownElement4 = document.getElementById('countdown4');

            // Add null check
            if (!countdownElement && !countdownElement2 && !countdownElement3 && !countdownElement4) {
                console.warn('Countdown elements not found');
                return;
            }

            const endTime = getEndTime();

            function updateClock() {
                const t = getTimeRemaining(endTime);

                if (countdownElement) {
                    countdownElement.innerHTML = `
                    <p><span>${padZero(t.days)}</span>Days</p> :
                    <p><span>${padZero(t.hours)}</span>Hours</p> :
                    <p><span>${padZero(t.minutes)}</span>Minutes</p> :
                    <p><span>${padZero(t.seconds)}</span>Seconds</p>
                `;
                }

                if (countdownElement2) {
                    countdownElement2.innerHTML = `
                        <div class="time-block">
                            <span>${padZero(t.days)}</span>
                            <small>Days</small>
                        </div>
                        <div class="colon">:</div>

                        <div class="time-block">
                            <span>${padZero(t.hours)}</span>
                            <small>Hours</small>
                        </div>
                        <div class="colon">:</div>

                        <div class="time-block">
                            <span>${padZero(t.minutes)}</span>
                            <small>Minutes</small>
                        </div>
                        <div class="colon">:</div>

                        <div class="time-block">
                            <span>${padZero(t.seconds)}</span>
                            <small>Seconds</small>
                        </div>
                    `;
                }

                if (countdownElement3) {
                    countdownElement3.innerHTML = `
                        <div class="time-block">
                            <span>${padZero(t.days)}</span>
                            <small>Days</small>
                        </div>
                        <div class="colon">:</div>

                        <div class="time-block">
                            <span>${padZero(t.hours)}</span>
                            <small>Hours</small>
                        </div>
                        <div class="colon">:</div>

                        <div class="time-block">
                            <span>${padZero(t.minutes)}</span>
                            <small>Minutes</small>
                        </div>
                        <div class="colon">:</div>

                        <div class="time-block">
                            <span>${padZero(t.seconds)}</span>
                            <small>Seconds</small>
                        </div>
                    `;
                }


                if (countdownElement4) {
                    countdownElement4.innerHTML = `
                        <div class="time-block">
                            <span>${padZero(t.days)}</span>
                            <small>Days</small>
                        </div>
                        <div class="colon">:</div>

                        <div class="time-block">
                            <span>${padZero(t.hours)}</span>
                            <small>Hours</small>
                        </div>
                        <div class="colon">:</div>

                        <div class="time-block">
                            <span>${padZero(t.minutes)}</span>
                            <small>Minutes</small>
                        </div>
                        <div class="colon">:</div>

                        <div class="time-block">
                            <span>${padZero(t.seconds)}</span>
                            <small>Seconds</small>
                        </div>
                    `;
                }


                if (t.total <= 0) {
                    clearInterval(timeInterval);
                    if (countdownElement) countdownElement.innerHTML = "Time's up!";
                    if (countdownElement2) countdownElement2.innerHTML = "Time's up!";
                    if (countdownElement3) countdownElement3.innerHTML = "Time's up!";
                    if (countdownElement4) countdownElement4.innerHTML = "Time's up!";
                }
            }

            updateClock();
            const timeInterval = setInterval(updateClock, 1000);
        }


        // Only use DOMContentLoaded
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', initializeClock);
        } else {
            // DOM is already loaded
            initializeClock();
        }

        // Set displayed date text
        document.getElementById("month-last-date").textContent = "15 Oct 2026";
        document.getElementById("month-last-date2").textContent = "15 Oct 2026";
        // document.getElementById("month-last-date3").textContent = "15 Oct 2026";
        document.getElementById("month-last-date4").textContent = "15 Oct 2026";
    </script>


